import{_ as e,o as r,c as a,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const h=JSON.parse('{"title":"Troubleshoot your RAG project","description":"Diagnose missing documents, irrelevant retrieval, model failures, bad citations and deployment without destructive resets.","frontmatter":{"title":"Troubleshoot your RAG project","description":"Diagnose missing documents, irrelevant retrieval, model failures, bad citations and deployment without destructive resets."},"headers":[],"relativePath":"students/stuck.md","filePath":"students/stuck.md","lastUpdated":1794376220000}'),s={name:"students/stuck.md"};function n(i,t,d,c,l,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="stuck-find-the-first-broken-step" tabindex="-1">Stuck? Find the first broken step <a class="header-anchor" href="#stuck-find-the-first-broken-step" aria-label="Permalink to &quot;Stuck? Find the first broken step&quot;">​</a></h1><p>You do not need to debug the entire application at once. Trace <strong>one source and one question</strong> from import to visible answer. Record expected versus actual behavior. Use <a href="./prompts#debug-prompt">the debugging agent prompt</a> with redacted output.</p><table tabindex="0"><thead><tr><th>What you see</th><th>First safe check</th><th>Likely next action</th></tr></thead><tbody><tr><td>No source in the database</td><td>Count imported rows and source IDs</td><td>Inspect path, permissions, parser and importer error</td></tr><tr><td>Duplicate rows after reimport</td><td>Import twice, compare IDs/counts</td><td>Add stable IDs and an update/skip rule</td></tr><tr><td>Search finds nothing</td><td>Query the index directly, inspect stored text</td><td>Check chunking, tokenization, model/index readiness</td></tr><tr><td>Irrelevant vector results</td><td>Confirm corpus/query embedding model IDs, inspect scores</td><td>Compare a keyword baseline; improve corpus/chunks/filters</td></tr><tr><td>Graph traversal gives wrong facts</td><td>Inspect stored edges and supporting passages</td><td>Repair extraction/identity decisions and provenance</td></tr><tr><td>Model responds but ignores documents</td><td>Print the <strong>redacted</strong> retrieved context before the model call</td><td>Fix retrieval or context selection before rewriting prompts</td></tr><tr><td>Citation does not match answer</td><td>Open source ID and passage, compare claim</td><td>Correct citation wiring, add grounded evaluation</td></tr><tr><td>Model refuses or endpoint fails</td><td>Check server logs for status and readiness, not tokens</td><td>Confirm configured provider, access and resource limit</td></tr><tr><td>Local app works but hosted app fails</td><td>Compare runtime config/health without exposing secrets</td><td>Check proxy, HTTPS, bind address, environment and persistence</td></tr><tr><td>Works until restart</td><td>Restart a test instance and read persistent state</td><td>Move durable data outside disposable container storage</td></tr></tbody></table><h2 id="diagnostic-order" tabindex="-1">Diagnostic order <a class="header-anchor" href="#diagnostic-order" aria-label="Permalink to &quot;Diagnostic order&quot;">​</a></h2><ol><li><strong>Source:</strong> Can you open the original document and see its stable ID?</li><li><strong>Stored representation:</strong> Can you inspect real chunks/metadata or graph edges?</li><li><strong>Retrieval:</strong> Can you run one question without generation and see actual evidence IDs?</li><li><strong>Generation:</strong> Is a real configured model called, and what authorized context did it receive?</li><li><strong>Browser and deployment:</strong> Can the hosted UI show the source and answer after a restart?</li></ol><p>Do not solve a retrieval problem by asking the model to be more confident.</p><h2 id="two-safe-fallbacks" tabindex="-1">Two safe fallbacks <a class="header-anchor" href="#two-safe-fallbacks" aria-label="Permalink to &quot;Two safe fallbacks&quot;">​</a></h2><p>If advanced retrieval is blocked, demonstrate a <strong>keyword baseline</strong> to identify whether import and source mapping work, then return to the selected vector/graph implementation. Label the baseline; it is not a finished substitute for the assigned method.</p><p>If your model is blocked, demonstrate real import/retrieval and mark generation as incomplete. Investigate existing supported local/shared/provider access rather than buying hardware or silently inserting canned answers. A mock can test UI wiring but must remain labeled.</p><h2 id="what-to-bring-to-class-or-office-hours" tabindex="-1">What to bring to class or office hours <a class="header-anchor" href="#what-to-bring-to-class-or-office-hours" aria-label="Permalink to &quot;What to bring to class or office hours&quot;">​</a></h2><p>Your repo and URL, the <strong>single action</strong> you attempted, expected result, actual redacted error, source ID or query, and what you tried. Never share passwords, API keys, full .env files or private student material.</p><p><a href="./build">Small build path</a> · <a href="./check">Verification worksheet</a> · <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/projects/individual.md" target="_blank" rel="noreferrer">Official course brief</a></p>',12)])])}const m=e(s,[["render",n]]);export{h as __pageData,m as default};
